class Solution {
public:
    int numberOfWays(int numPeople) {
        const long long MOD = 1000000007LL;
        int pairs = numPeople / 2;
        vector<long long> dp(pairs + 1, 0);
        dp[0] = 1;
        for (int n = 1; n <= pairs; ++n) {
            for (int left = 0; left < n; ++left) {
                dp[n] = (dp[n] + dp[left] * dp[n - 1 - left]) % MOD;
            }
        }
        return static_cast<int>(dp[pairs]);
    }
};
